export function creativePersonalText(message: string, locale: WorkspaceLocale): string {
  const localeIndex: Readonly<Record<Exclude<WorkspaceLocale, 'en-US'>, number>> = { 'de-DE': 0, 'es-ES': 1, 'it-IT': 2, 'ja-JP': 3, 'ru-RU': 4, 'zh-CN': 5 };
  return COPY[locale][message] ?? EXTRA_COPY[locale][message] ?? TASK_EXTRA_COPY[locale][message] ?? DOMAIN_EXTRA_COPY[locale][message] ?? (locale === 'en-US' ? message : ADVANCED_SURFACE_COPY[message]?.[localeIndex[locale]] ?? message);
}

export function creativePersonalMessageKeys(): readonly string[] {
  return [...new Set([...Object.keys(COPY['de-DE']), ...Object.keys(EXTRA_COPY['de-DE']), ...Object.keys(TASK_EXTRA_COPY['de-DE']), ...Object.keys(DOMAIN_EXTRA_COPY['de-DE']), ...Object.keys(ADVANCED_SURFACE_COPY)])];
}
